import { useEffect, useState } from 'react';

/**
 * Track which of the given element ids is currently the "active" one in the
 * viewport (the highest one crossing the reading line). Powers the TOC.
 */
export function useScrollSpy(ids: string[], topOffset = 120): string | null {
  const [active, setActive] = useState<string | null>(ids[0] ?? null);
  const key = ids.join('|');

  useEffect(() => {
    if (ids.length === 0) return;
    const elements = ids
      .map((id) => document.getElementById(id))
      .filter((el): el is HTMLElement => el !== null);
    if (elements.length === 0) return;

    const visible = new Map<string, number>();

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            visible.set(entry.target.id, entry.boundingClientRect.top);
          } else {
            visible.delete(entry.target.id);
          }
        }
        if (visible.size > 0) {
          // The visible element nearest the top of the reading area wins.
          const top = [...visible.entries()].sort((a, b) => a[1] - b[1])[0];
          setActive(top[0]);
        }
      },
      { rootMargin: `-${topOffset}px 0px -55% 0px`, threshold: [0, 1] },
    );

    elements.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, topOffset]);

  return active;
}

