import type { Item } from '../../types/conversation';
import { itemAnchor, itemTitle } from '../../lib/conversation';
import { StatusDot } from '../ui/StatusPill';

interface TocListProps {
  items: Item[];
  activeId: string | null;
  onNavigate?: () => void;
}

/** The shared table-of-contents list (used by both the desktop rail and the mobile sheet). */
export function TocList({ items, activeId, onNavigate }: TocListProps) {
  return (
    <nav aria-label="Sommaire">
      <ol className="space-y-0.5">
        {items.map((item, index) => {
          const anchor = itemAnchor(item.id);
          const active = activeId === anchor;
          return (
            <li key={item.id}>
              <a
                href={`#${anchor}`}
                onClick={onNavigate}
                className={`group flex items-start gap-2.5 rounded-md px-2 py-1.5 transition-colors ${
                  active ? 'bg-copper-tint/60' : 'hover:bg-paper-deep/60'
                }`}
              >
                <span
                  className={`numeral mt-px w-5 shrink-0 text-right text-xs ${
