import { useCallback, useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import type { Item, ItemKind, Conversation } from '../types/conversation';
import { ITEM_KINDS, ITEM_KIND_LABELS, itemCountsTowardCompletion } from '../types/conversation';
