export function ConversationPage() {
  const { slug = '', id = '' } = useParams();
  const navigate = useNavigate();
  const {
    conversation,
    loadState,
    loadError,
    saveState,
    saveError,
    conflict,
    dirty,
    updateItem,
    save,
    reload,
    setConversation,
  } = useConversation(slug, id);

  const [tocOpen, setTocOpen] = useState(false);
  const [toast, setToast] = useState<string | null>(null);
  const [externalChange, setExternalChange] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [qualityOpen, setQualityOpen] = useState(false);

  // Git History Sidebar State
  const [historyOpen, setHistoryOpen] = useState(false);

  const items = conversation?.items ?? [];
  const anchors = items.map((i) => itemAnchor(i.id));
  const activeAnchor = useScrollSpy(anchors);

  // Live updates: if Claude (or another tab) rewrites this file, refresh when
  // we have no unsaved edits; otherwise surface a non-destructive banner.
  useServerEvents(
    useCallback(
      (event) => {
        if (event.type !== 'conversations-changed') return;
        if (event.slug && event.slug !== slug) return;
        if (event.id && event.id !== id) return;
        if (dirty) {
          setExternalChange(true);
        } else {
          reload();
          setToast('Conversation mise à jour');
        }
      },
      [slug, id, dirty, reload],
    ),
  );

  useEffect(() => {
    if (saveState === 'saved') {
      setToast('Réponses enregistrées · Claude pourra les relire');
      setValidationErrors([]);
    }
  }, [saveState]);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 3500);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    if (!tocOpen) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setTocOpen(false);
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [tocOpen]);

  if (loadState === 'loading' || loadState === 'idle') {
    return (
      <Wrap>
        <div className="space-y-5 py-12">
          <div className="h-10 w-2/3 animate-pulse rounded bg-paper-deep" />
          <div className="h-48 animate-pulse rounded-lg bg-paper-card" />
          <div className="h-48 animate-pulse rounded-lg bg-paper-card" />
        </div>
      </Wrap>
    );
  }

  if (loadState === 'error' || !conversation) {
    return (
      <Wrap>
        <div className="my-16 rounded-lg border border-line bg-paper-card p-10 text-center">
          <p className="numeral text-5xl text-copper/25">404</p>
