          </span>
          <span className="font-mono text-xs text-ink-soft">{answered}/{total}</span>
          <span aria-hidden className="text-ink-faint">☰</span>
        </button>
      </div>

      <div className="py-8 sm:py-10 xl:grid xl:grid-cols-[minmax(0,1fr)_13.5rem] xl:gap-10 xl:py-12">
