                <span className="block h-full rounded-full bg-copper transition-all" style={{ width: `${pct}%` }} />
              </span>
              <span className="font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint">
                {answered}/{total} traités · maj {formatRelative(conversation.updatedAt)}
              </span>
            </div>
          )}

          {externalChange && (
            <div className="mt-6 flex items-center gap-3 rounded-lg border border-status-progress/40 bg-status-progress-bg/60 px-4 py-3 text-sm text-status-progress">
              <span className="flex-1">Ce fichier a changé sur le disque (Claude l’a peut-être réécrit).</span>
              <button
                onClick={() => { setExternalChange(false); reload(); }}
                className="font-medium underline underline-offset-2"
              >
                Recharger
              </button>
            </div>
          )}

          <hr className="rule my-9" />

          {isEditing ? (
            <div className="space-y-10">
              {items.map((item, index) => (
                <ItemEditor
                  key={item.id}
                  item={item}
                  index={index}
                  total={items.length}
                  onUpdate={(patch) => {
                    setConversation(prev => {
                      if (!prev) return prev;
                      const newItems = [...prev.items];
                      newItems[index] = { ...newItems[index], ...patch } as Item;
                      return { ...prev, items: newItems };
                    });
                  }}
                  onDelete={() => {
                    setConversation(prev => {
                      if (!prev) return prev;
                      return {
                        ...prev,
                        items: prev.items.filter((_, idx) => idx !== index)
                      };
                    });
                  }}
                  onMoveUp={() => {
                    if (index === 0) return;
                    setConversation(prev => {
                      if (!prev) return prev;
                      const newItems = [...prev.items];
                      const temp = newItems[index];
                      newItems[index] = newItems[index - 1];
                      newItems[index - 1] = temp;
                      return { ...prev, items: newItems };
                    });
                  }}
                  onMoveDown={() => {
                    if (index === items.length - 1) return;
                    setConversation(prev => {
                      if (!prev) return prev;
                      const newItems = [...prev.items];
                      const temp = newItems[index];
                      newItems[index] = newItems[index + 1];
                      newItems[index + 1] = temp;
                      return { ...prev, items: newItems };
                    });
                  }}
                />
              ))}

              <div className="flex flex-wrap gap-2 rounded-lg border border-dashed border-line p-6 bg-paper-raised justify-center">
                <span className="w-full text-center text-xs font-mono uppercase tracking-wider text-ink-faint mb-2">Ajouter un nouvel élément</span>
                {ITEM_KINDS.map((kind) => (
                  <button
                    key={kind}
                    type="button"
                    onClick={() => {
                      const newItem = createDefaultItem(kind);
                      setConversation(prev => {
                        if (!prev) return prev;
                        return {
                          ...prev,
                          items: [...prev.items, newItem]
                        };
                      });
                    }}
                    className="rounded border border-line bg-paper px-3 py-1 text-xs font-mono text-ink hover:border-copper hover:bg-paper-card transition-colors cursor-pointer"
                  >
                    + {ITEM_KIND_LABELS[kind]}
                  </button>
                ))}
              </div>
            </div>
          ) : (
            <div className="space-y-14">
              {items.map((item, index) => (
                <ItemRenderer key={item.id} item={item} index={index} onChange={(patch) => updateItem(item.id, patch)} />
              ))}
            </div>
          )}

