                  onClick={handleSave}
                  loading={saveState === 'saving'}
                  disabled={!dirty && saveState !== 'error'}
                >
                  {isEditing ? 'Enregistrer le modèle/les modifs' : 'Enregistrer les réponses'}
                </Button>
              )}
            </div>
          </div>
        </div>

