            <div className="mb-4 flex items-center justify-between">
              <p className="eyebrow text-copper">Sommaire</p>
              <button onClick={() => setTocOpen(false)} aria-label="Fermer" className="text-ink-faint hover:text-ink">✕</button>
            </div>
            <TocList items={items} activeId={activeAnchor} onNavigate={() => setTocOpen(false)} />
          </div>
        </div>
      )}

      {/* Git History Sidebar Panel */}
      <GitHistoryPanel
        isOpen={historyOpen}
        onClose={() => setHistoryOpen(false)}
        projectSlug={slug}
