interface ItemShellProps {
  item: Item;
  index: number;
  children: ReactNode;
  /** Hide the comment field (e.g. for purely informational notes). */
  comment?: ReactNode;
}

/**
 * The numbered, generously-spaced frame shared by every item kind. Big serif
 * numeral + monospace eyebrow + status, then the prompt, optional context, the
 * kind-specific control, and an optional comment field.
 */
export function ItemShell({ item, index, children, comment }: ItemShellProps) {
  return (
    <article
      id={itemAnchor(item.id)}
      className="rise scroll-mt-28"
      style={{ animationDelay: `${Math.min(index, 8) * 60}ms` }}
    >
      <div className="mb-3 flex items-center gap-3.5">
        <span className="numeral text-2xl leading-none text-copper">
          {String(index + 1).padStart(2, '0')}
        </span>
        <span className="eyebrow text-ink-faint">{ITEM_KIND_LABELS[item.kind]}</span>
        <StatusPill status={item.status} size="sm" className="ml-auto" />
      </div>

      {(item.priority || item.dueAt || item.blockedReason) && (
        <div className="mb-3 flex flex-wrap gap-2 font-mono text-[0.6875rem] uppercase tracking-wide">
          {item.priority && (
            <span className="rounded-full border border-copper/25 bg-copper/10 px-2 py-0.5 text-copper-deep">
              Priorité {priorityLabel(item.priority)}
            </span>
          )}
          {item.dueAt && (
            <span className="rounded-full border border-line bg-paper-card px-2 py-0.5 text-ink-soft">
              Échéance {formatShortDate(item.dueAt)}
            </span>
          )}
          {item.blockedReason && (
            <span className="rounded-full border border-status-progress/30 bg-status-progress-bg px-2 py-0.5 text-status-progress">
              Bloqué
            </span>
          )}
        </div>
      )}

      <h3 className="conversation-heading max-w-[38ch] font-display text-[1.45rem] leading-[1.22] text-ink sm:text-[1.55rem]">
        {item.prompt}
      </h3>
      {item.context && (
        <Markdown className="mt-3 text-[0.96rem] text-ink-soft">{item.context}</Markdown>
      )}
      {item.blockedReason && (
        <p className="mt-3 rounded-lg border border-status-progress/25 bg-status-progress-bg/50 px-3 py-2 text-sm text-status-progress">
          {item.blockedReason}
        </p>
      )}

      <div className="mt-6">{children}</div>
      {comment}
    </article>
  );
}

function priorityLabel(priority: NonNullable<Item['priority']>) {
  const labels: Record<NonNullable<Item['priority']>, string> = {
    low: 'basse',
    normal: 'normale',
    high: 'haute',
    urgent: 'urgente',
  };
  return labels[priority];
}

function formatShortDate(value: string) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return date.toLocaleDateString('fr-FR', { day: '2-digit', month: 'short' });
}

/** A subtle, collapsible optional comment field reused by every item. */
export function CommentField({
  value,
  onChange,
  label = 'Commentaire',
}: {
  value: string;
  onChange: (value: string) => void;
  label?: string;
}) {
  const id = useId();
  const [open, setOpen] = useState(value.trim().length > 0);

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="mt-3 inline-flex items-center gap-1.5 font-mono text-[0.6875rem] uppercase tracking-wide text-ink-faint transition-colors hover:text-copper"
      >
        <span aria-hidden className="text-sm leading-none">＋</span>
        {label}
      </button>
    );
  }

  return (
    <div className="mt-3">
      <Textarea
        id={id}
        label={`${label} (optionnel)`}
        placeholder="Ajoutez une précision pour Claude…"
        value={value}
        rows={2}
        onChange={(event) => onChange(event.target.value)}
      />
    </div>
  );
}

/** Helper to keep answeredAt stable: stamp only on the transition to answered. */
export function stampAnsweredAt(current: string | undefined, isAnswered: boolean): string | undefined {
  if (!isAnswered) return undefined;
  return current ?? new Date().toISOString();
}

export type { ItemStatus };

