interface Props {
  item: NoteItemType;
  index: number;
  onChange: (patch: Partial<Item>) => void;
}

/**
 * A note is a "support / information" block from Claude. It uses a distinct
 * panel treatment rather than the standard control frame. When `requiresAck`
 * it shows an acknowledge toggle; otherwise it is purely informational and
 * never blocks completion.
 */
export function NoteItem({ item, index, onChange }: Props) {
  const acknowledged = item.response?.acknowledged ?? false;
  const requiresAck = item.requiresAck ?? false;

  function toggleAck() {
    const next = !acknowledged;
    onChange({
      response: next ? { acknowledged: true } : undefined,
      status: next ? 'answered' : 'pending',
      answeredAt: next ? item.answeredAt ?? new Date().toISOString() : undefined,
    });
  }

  return (
    <article
      id={itemAnchor(item.id)}
      className="rise scroll-mt-28"
      style={{ animationDelay: `${Math.min(index, 8) * 60}ms` }}
    >
      <div className="mb-3 flex items-center gap-3.5">
        <span className="numeral text-2xl leading-none text-ink-faint">
          {String(index + 1).padStart(2, '0')}
        </span>
        <span className="eyebrow text-ink-faint">{ITEM_KIND_LABELS[item.kind]}</span>
        {requiresAck && <StatusPill status={item.status} size="sm" className="ml-auto" />}
      </div>

      <div className="rounded-lg border-l-2 border-copper/50 border-y border-r border-line bg-paper-card/70 px-4 py-3.5">
        <h3 className="conversation-heading font-display text-xl leading-snug text-ink">{item.prompt}</h3>
        {item.context && (
          <Markdown className="mt-2 text-sm italic text-ink-faint">{item.context}</Markdown>
        )}
        <div className="mt-2.5 text-[0.95rem]">
          <Markdown>{item.body}</Markdown>
        </div>

        {requiresAck && (
          <div className="mt-3.5 border-t border-line-soft pt-3">
            <button
              type="button"
              aria-pressed={acknowledged}
              onClick={toggleAck}
              className={`inline-flex items-center gap-2 rounded-lg border px-3.5 py-2 text-sm font-medium transition-colors ${
                acknowledged
                  ? 'border-status-done bg-status-done-bg text-status-done'
                  : 'border-line bg-paper-raised text-ink hover:border-copper/45'
              }`}
            >
              <span aria-hidden>{acknowledged ? '✓' : '○'}</span>
              {acknowledged ? 'Lu et compris' : "J'ai lu"}
            </button>
          </div>
        )}
      </div>

      {requiresAck && (
        <CommentField value={item.comment ?? ''} onChange={(v) => onChange({ comment: v || undefined })} />
      )}
    </article>
  );
}

