import { useEffect, useState } from 'react';

/**
 * Track which of the given element ids is currently the "active" one in the
 * viewport (the highest one crossing the reading line). Powers the TOC.
 */
export function useScrollSpy(ids: string[], topOffset = 120): string | null {
  const [active, setActive] = useState<string | null>(ids[0] ?? null);
  const key = ids.join('|');

  useEffect(() => {
    if (ids.length === 0) {
      setActive(null);
      return;
    }

    let frame: number | undefined;
    let shortTimeout: number | undefined;
    let longTimeout: number | undefined;

    const syncFromHash = () => {
      const hash = decodeURIComponent(window.location.hash.slice(1));
      if (!ids.includes(hash)) return;

      const alignToHash = () => {
        const target = document.getElementById(hash);
        if (target) {
          window.scrollTo({ top: target.getBoundingClientRect().top + window.scrollY - topOffset - 1 });
        }
        setActive(hash);
      };

      alignToHash();
      frame = window.requestAnimationFrame(() => {
        alignToHash();
        shortTimeout = window.setTimeout(alignToHash, 250);
        longTimeout = window.setTimeout(alignToHash, 700);
      });
      void document.fonts?.ready.then(alignToHash);
    };

    syncFromHash();
    window.addEventListener('hashchange', syncFromHash);
    return () => {
      window.removeEventListener('hashchange', syncFromHash);
      if (frame !== undefined) window.cancelAnimationFrame(frame);
      if (shortTimeout !== undefined) window.clearTimeout(shortTimeout);
      if (longTimeout !== undefined) window.clearTimeout(longTimeout);
    };
  }, [key, topOffset]);

  useEffect(() => {
    if (ids.length === 0) return;
    const elements = ids
      .map((id) => document.getElementById(id))
      .filter((el): el is HTMLElement => el !== null);
    if (elements.length === 0) return;

    const updateActive = () => {
      const current = elements
        .map((element) => ({ id: element.id, top: element.getBoundingClientRect().top }))
        .sort((a, b) => a.top - b.top);

      // Prefer the last section that has crossed the reading line; while the
      // page is above the first section, keep the nearest upcoming one active.
      const readingLine = topOffset + 8;
      const crossed = current.filter((entry) => entry.top <= readingLine);
      setActive(crossed.at(-1)?.id ?? current[0]?.id ?? null);
    };

    const observer = new IntersectionObserver(
      () => updateActive(),
      { rootMargin: `-${topOffset}px 0px -55% 0px`, threshold: [0, 1] },
    );

    updateActive();
    elements.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, topOffset]);

  return active;
}

